import{_ as r,o,c as n,a5 as t}from"./chunks/framework.DJo0M80U.js";const l=JSON.parse('{"title":"JD13 完全数计算","description":"简单 通过率：51.54% 时间限制：1秒 空间限制：32M 描述 完全数（Perfect number），又称完美数或完备数，是一些特殊的自然数。 它所有的真因子（即除了自身以外的约数）的和（即因子函数），恰好等于它本身。 例如：28，它有约数1、2、4、7、14、28，除去它。","frontmatter":{"title":"JD13 完全数计算","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"简单 通过率：51.54% 时间限制：1秒 空间限制：32M 描述 完全数（Perfect number），又称完美数或完备数，是一些特殊的自然数。 它所有的真因子（即除了自身以外的约数）的和（即因子函数），恰好等于它本身。 例如：28，它有约数1、2、4、7、14、28，除去它。","sidebarWeight":75,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/华为简单[31个]/JD13 完全数计算.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD13 完全数计算.md","filePath":"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD13 完全数计算.md"}'),a={name:"posts/前端面试与实战/03-算法训练/华为简单[31个]/JD13 完全数计算.md"};function i(p,e,s,d,u,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<div><h1 id="jd13-完全数计算" tabindex="-1">JD13 完全数计算 <a class="header-anchor" href="#jd13-完全数计算" aria-label="Permalink to &quot;JD13 完全数计算&quot;">​</a></h1><blockquote><p>本节目标：理解“JD13 完全数计算”的核心思路，并能把它用于实际开发或面试表达。 简单 通过率：51.54% 时间限制：1秒 空间限制：32M <strong>描述</strong> 完全数（Perfect number），又称完美数或完备数，是一些特殊的自然数。 它所有的真因子（即除了自身以外的约数）的和（即因子函数），恰好等于它本身。 例如：28，它有约数1、2、4、7、14、28，除去它本身28外，其余5个数相加，1+2+4+7+14=28。</p></blockquote><p>输入n，请输出n以内(含n)完全数的个数。</p><p>数据范围： 1≤<em>n</em>≤5×105 <strong>输入描述：</strong> 输入一个数字n <strong>输出描述：</strong> 输出不超过n的完全数的个数 <strong>示例1</strong> 输入： 1000 ==复制== 输出： 3</p><p>要找出不超过<code>n</code>的完全数的个数，我们可以对每一个数<code>x</code>（从1到<code>n</code>），检查它是否是完全数。判断一个数是否是完全数的方法是：找出它的所有真因子（即除了自身以外的约数），计算这些真因子的和，如果这个和等于原数，则它是完全数。</p><p>这个方法的时间复杂度较高，特别是对于较大的<code>n</code>值，但对于较小的<code>n</code>（如题目中的数据范围），这种方法是可行的。 def is_perfect_number(num):</p><h1 id="计算一个数的所有真因子之和" tabindex="-1">计算一个数的所有真因子之和 <a class="header-anchor" href="#计算一个数的所有真因子之和" aria-label="Permalink to &quot;计算一个数的所有真因子之和&quot;">​</a></h1><p>sum_of_factors = sum([i for i in range(1, num) if num % i == 0])</p><h1 id="如果真因子之和等于原数-则是完全数" tabindex="-1">如果真因子之和等于原数，则是完全数 <a class="header-anchor" href="#如果真因子之和等于原数-则是完全数" aria-label="Permalink to &quot;如果真因子之和等于原数，则是完全数&quot;">​</a></h1><p>return sum_of_factors == num</p><p>def count_perfect_numbers(n):</p><h1 id="计算不超过n的完全数的个数" tabindex="-1">计算不超过n的完全数的个数 <a class="header-anchor" href="#计算不超过n的完全数的个数" aria-label="Permalink to &quot;计算不超过n的完全数的个数&quot;">​</a></h1><p>count = 0 for i in range(1, n + 1): if is_perfect_number(i): count += 1 return count</p><h1 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="输出不超过n的完全数的个数" tabindex="-1">输出不超过n的完全数的个数 <a class="header-anchor" href="#输出不超过n的完全数的个数" aria-label="Permalink to &quot;输出不超过n的完全数的个数&quot;">​</a></h1><p>print(count_perfect_numbers(n))</p><p>优化方法</p><ul><li>所有完美数都是偶数</li><li>大于这个数1/2的公因子是不存在的，第二次循环次数减少了一半</li><li>一个数的约数总是成对出现的，我们只要找平方根一侧的，别一侧的通过除法获得，如28，我们只找小于5的，找到4时，我们用28/4，得到7，这样减少遍历</li></ul><p>def get_sum_of_proper_divisors(number): &quot;&quot;&quot;计算并返回一个数的所有真因子之和。&quot;&quot;&quot; sum_of_divisors = 1 # 初始化为1，因为1是每个数的因子</p><h1 id="遍历可能的因子-只需检查到该数的平方根" tabindex="-1">遍历可能的因子，只需检查到该数的平方根 <a class="header-anchor" href="#遍历可能的因子-只需检查到该数的平方根" aria-label="Permalink to &quot;遍历可能的因子，只需检查到该数的平方根&quot;">​</a></h1><p>for possible_divisor in range(2, int(number ** 0.5) + 1): if number % possible_divisor == 0: paired_divisor = number // possible_divisor if possible_divisor == paired_divisor: # 因子是平方根的情况 sum_of_divisors += possible_divisor else: sum_of_divisors += possible_divisor + paired_divisor return sum_of_divisors</p><p>def count_perfect_numbers(up_to): &quot;&quot;&quot;计算并返回不超过给定上限的完全数的数量。&quot;&quot;&quot; perfect_numbers = [] for num in range(2, up_to): if num == get_sum_of_proper_divisors(num): perfect_numbers.append(num) return len(perfect_numbers)</p><h1 id="读取输入并打印结果" tabindex="-1">读取输入并打印结果 <a class="header-anchor" href="#读取输入并打印结果" aria-label="Permalink to &quot;读取输入并打印结果&quot;">​</a></h1><p>upper_limit = int(input()) print(count_perfect_numbers(upper_limit))</p><p><strong>优化方法二</strong> 当数据范围较大时，逐个检查每个数是否为完美数的方法变得不可行，因为这种方法的时间复杂度较高。然而，鉴于完美数非常稀少，并且到目前为止已知的完美数都与<strong>梅森素数</strong>（Mersenne primes）紧密相关，我们可以利用这一性质来优化我们的算法。</p><p>到目前为止已知的所有完美数都是偶数，并且可以表示为<code>2^(p-1) * (2^p - 1)</code>的形式，其中<code>2^p - 1</code>是梅森素数。因此，我们只需要检查这种形式的数是否在我们的范围内，这样可以大大减少需要检查的数的数量。</p><p>由于数据范围<code>n</code>为<code>1≤n≤5×10^5</code>，我们只需要检查前几个梅森素数对应的完美数。目前已知的梅森素数对应的<code>p</code>值较小，例如2, 3, 5, 7, 13, 17, 19等。</p><p>下面是一个优化后的方法，它只检查这些特定形式的数：</p><p>def find_perfect_numbers(n):</p><h1 id="已知的梅森素数的指数p" tabindex="-1">已知的梅森素数的指数p <a class="header-anchor" href="#已知的梅森素数的指数p" aria-label="Permalink to &quot;已知的梅森素数的指数p&quot;">​</a></h1><p>primes = [2, 3, 5, 7, 13, 17, 19, 31] perfect_numbers = [] # 检查每个梅森素数对应的完美数是否小于等于n for p in primes: perfect_number = (2 ** (p - 1)) * ((2 ** p) - 1) if perfect_number &lt;= n: perfect_numbers.append(perfect_number) else: break return perfect_numbers</p><h1 id="输入-1" tabindex="-1">输入 <a class="header-anchor" href="#输入-1" aria-label="Permalink to &quot;输入&quot;">​</a></h1><p>n = int(input())</p><h1 id="找到不超过n的所有完美数" tabindex="-1">找到不超过n的所有完美数 <a class="header-anchor" href="#找到不超过n的所有完美数" aria-label="Permalink to &quot;找到不超过n的所有完美数&quot;">​</a></h1><p>perfect_numbers = find_perfect_numbers(n)</p><h1 id="输出完美数的个数" tabindex="-1">输出完美数的个数 <a class="header-anchor" href="#输出完美数的个数" aria-label="Permalink to &quot;输出完美数的个数&quot;">​</a></h1><p>print(len(perfect_numbers))</p><p>这段代码首先定义了一个包含已知梅森素数的指数<code>p</code>的列表。然后，它计算每个这样的<code>p</code>对应的完美数，并检查这些完美数是否不超过输入的<code>n</code>。如果一个完美数小于等于<code>n</code>，就将它添加到结果列表中。最后，输出不超过<code>n</code>的完美数的个数。</p><p>这种方法只检查少量特定的数，因此比逐个检查每个数是否为完美数的方法快得多，并且可以满足题目中对时间和空间的限制要求。</p></div>',1)])])}const f=r(a,[["render",i]]);export{l as __pageData,f as default};
